solution.solution.rs:
use std::fmt;
use std::hash::{Hash, Hasher};
use std::marker::PhantomData;

struct Id<T> {
    value: u64,
    _for: PhantomData<T>,
}

impl<T> Id<T> {
    fn new(value: u64) -> Self {
        Id { value, _for: PhantomData }
    }
    fn get(&self) -> u64 {
        self.value
    }
}

impl<T> Clone for Id<T> {
    fn clone(&self) -> Self {
        *self
    }
}
impl<T> Copy for Id<T> {}

impl<T> PartialEq for Id<T> {
    fn eq(&self, other: &Self) -> bool {
        self.value == other.value
    }
}
impl<T> Eq for Id<T> {}

impl<T> Hash for Id<T> {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.value.hash(state);
    }
}

impl<T> fmt::Display for Id<T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "#{}", self.value)
    }
}

struct IdGen<T> {
    last: u64,
    _for: PhantomData<T>,
}

impl<T> IdGen<T> {
    fn new() -> Self {
        IdGen { last: 0, _for: PhantomData }
    }
    fn next(&mut self) -> Id<T> {
        self.last += 1;
        Id::new(self.last)
    }
}

unitTests:
struct User;      // has no Clone, Copy, Eq or Hash of its own
struct Order;

test("ids", || {
    let mut users = IdGen::<User>::new();
    let a = users.next();
    let b = users.next();
    let a2 = a;               // Copy, although User is not
    check(a == a2);
    check(a != b);
    check_eq(b.get(), 2);
    check_eq(format!("{a} {b}"), "#1 #2");
});

test("usable as map keys", || {
    let mut names: std::collections::HashMap<Id<User>, &str> = std::collections::HashMap::new();
    names.insert(Id::new(7), "Ada");
    check_eq(names.get(&Id::new(7)), Some(&"Ada"));
    let mut orders = IdGen::<Order>::new();
    check_eq(orders.next().get(), 1);
});

